function u(t,e=40){const n=e>0?e:40,r=i=>Math.ceil(i/40*n);return t>=r(39)?9:t>=r(37)?8.5:t>=r(35)?8:t>=r(33)?7.5:t>=r(30)?7:t>=r(27)?6.5:t>=r(23)?6:t>=r(20)?5.5:t>=r(16)?5:t>=r(13)?4.5:t>=r(10)?4:t>=r(8)?3.5:t>=r(6)?3:2.5}function s(t,e){if(t.type==="fill-blank"){const n=Array.isArray(t.answer)?t.answer:[t.answer],r=e.trim().toLowerCase();return n.some(i=>r===String(i).trim().toLowerCase())}if(t.type==="map-label")return e.trim().toUpperCase()===String(t.answer).trim().toUpperCase();if(t.type==="multi-select"&&Array.isArray(t.answer)){const n=new Set(e.split(",").filter(Boolean).map(i=>Number(i))),r=new Set(t.answer);return n.size===r.size&&[...r].every(i=>n.has(i))}return e===String(t.answer)}function f(t,e){if(t.type!=="multi-select"||!Array.isArray(t.answer))return s(t,e)?1:0;const n=new Set(e.split(",").filter(Boolean).map(a=>Number(a))),r=new Set(t.answer);if(n.size>r.size)return 0;let i=0;for(const a of n)r.has(a)&&i++;return i}function o(t){const e=Math.floor(t/60),n=t%60;return`${String(e).padStart(2,"0")}:${String(n).padStart(2,"0")}`}export{u as bandScore,o as formatCountdown,s as isCorrect,f as multiSelectScore};
